(function(){'use strict';
const clone=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),mod=(x,m)=>((x%m)+m)%m,gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);
function validate(raw){const s=clone(raw);if(!['chain','open','shift','rebuild','perfect','cuckoo','bloom','horner','robin'].includes(s.operation))throw Error('Choose a supported hashing operation.');if(!Number.isInteger(s.capacity)||s.capacity<2||s.capacity>(s.operation==='horner'?31:13))throw Error('Capacity must be 2–13, or 2–31 for polynomial arithmetic.');if(!Array.isArray(s.keys)||s.keys.length<1||s.keys.length>16||s.keys.some(x=>!Number.isInteger(x)||Math.abs(x)>999))throw Error('Supply one through sixteen integer keys from -999 through 999.');s.policy=s.policy||'linear';if(!['linear','square','alternating','triangular','double'].includes(s.policy))throw Error('Choose a supported probe policy.');s.step=s.step??1;if(!Number.isInteger(s.step)||Math.abs(s.step)>13)throw Error('Fixed step must be an integer from -13 through 13.');s.commands=s.commands||[];if(!Array.isArray(s.commands)||s.commands.some(c=>!['put','get','delete'].includes(c.type)||!Number.isInteger(c.key)||Math.abs(c.key)>999))throw Error('Commands require put, get or delete and an integer key.');if(s.operation==='rebuild'&&(!Number.isInteger(s.newCapacity)||s.newCapacity<2||s.newCapacity>13))throw Error('New capacity must be an integer from 2 through 13.');if(s.operation==='bloom'){s.hashes=s.hashes??3;if(!Number.isInteger(s.hashes)||s.hashes<1||s.hashes>5)throw Error('Bit-hash count must be one through five.');}if(s.operation==='horner'){s.base=s.base??5;if(!Number.isInteger(s.base)||Math.abs(s.base)>31)throw Error('Polynomial base must be an integer from -31 through 31.');}if(s.operation==='chain'&&(s.capacity>8||s.keys.length+s.commands.filter(c=>c.type==='put').length>8))throw Error('Compact chaining accepts at most eight keys and eight buckets.');
if(s.operation==='perfect'){const counts=Array(s.capacity).fill(0);for(const k of s.keys)counts[mod(k,s.capacity)]++;if(Math.max(...counts)>3||counts.filter(Boolean).length>4)throw Error('Compact perfect placement accepts at most three keys per bucket and four occupied buckets.');}
if(s.operation==='rebuild'&&(s.policy!=='linear'||s.newCapacity<new Set(s.keys).size))throw Error('Rebuild requires linear probing and enough new slots for distinct keys.');
if(s.operation==='cuckoo'&&new Set(s.keys).size!==s.keys.length)throw Error('Cuckoo placement accepts distinct keys.');
if(s.operation==='robin'&&new Set(s.keys).size>s.capacity)throw Error('Robin Hood placement requires sufficient slots.');return s;}
function probe(k,i,s){const h=mod(k,s.capacity),m=s.capacity;let d=i;if(s.policy==='square')d=i*i;if(s.policy==='alternating')d=i===0?0:(i%2?1:-1)*Math.ceil(i/2)**2;if(s.policy==='triangular')d=i*(i+1)/2;if(s.policy==='double')d=i*(s.keyStep?1+mod(k,7):s.step);return mod(h+d,m);}
function evaluate(raw){const s=validate(raw),states=[],m=s.capacity;let slots=Array(m).fill(null),buckets=Array.from({length:m},()=>[]),probes=0,comparisons=0,links=0,moves=0,cursor=null,key=null,route=[],answer=null,extra={},serial=0;
const mapState=()=>({slots,buckets,probes,comparisons,links,moves,cursor,key,route,answer,extra});
function snap(action,why,complete=false,formula=''){
if(!formula&&cursor!==null&&key!==null&&['open','shift','rebuild','robin'].includes(s.operation)){formula=`h(${key})=${key}\\bmod${s.capacity}=${mod(key,s.capacity)}`;if(s.operation==='shift'&&extra.distanceToHole!==undefined)formula=`D(h,u)=${extra.distanceToHole} \\quad D(h,v)=${extra.distanceToSlot}`;}
states.push({...clone(mapState()),action,why,complete,formula,kind:s.operation,capacity:s.capacity,policy:s.policy});}
const ids=()=>slots.filter(x=>x&&x!=='DELETED').map(x=>x.key);
function runOpen(c){key=c.key;route=[];cursor=null;answer=null;let first=-1;const seen=new Set();snap('Begin '+c.type,'Use the same deterministic route for this key; markers do not equal user keys.');
 for(let i=0;i<m;i++){const j=probe(key,i,s);route.push(j);cursor=j;probes++;const v=slots[j];snap('Inspect slot '+j,v==='DELETED'?'Remember a deleted slot but continue duplicate/membership search.':v?'Compare the live key with the requested key.':'An EMPTY slot certifies absence along this route.');
  if(v&&v!=='DELETED'){comparisons++;if(v.key===key){if(c.type==='delete')slots[j]='DELETED';if(c.type==='put')v.value=c.value??key;answer={status:c.type==='delete'?'deleted':c.type==='put'?'updated':'found',index:j};snap('Complete '+c.type,'The matching record is handled once; update does not add a live entry.',true);return;}}
  if(v==='DELETED'&&first<0)first=j;
  if(v===null){if(c.type==='put'){const target=first<0?j:first;slots[target]={key,value:c.value??key,id:'K'+serial++};answer={status:'inserted',index:target};snap('Commit insertion','Absence is established; reuse the first remembered deleted slot when available.',true);}else{answer={status:'absent'};snap('Complete miss','EMPTY terminates this route and no equal live key was found.',true);}return;}
  seen.add(j);
 }
 if(c.type==='put'&&first>=0){slots[first]={key,value:c.value??key,id:'K'+serial++};answer={status:'inserted',index:first};snap('Reuse after bounded scan','The complete declared probe limit found no duplicate, so the remembered marker can be reused.',true);}else{answer={status:c.type==='put'?'route_exhausted':'absent',distinctVisited:seen.size};snap('Stop at finite route limit','Route exhaustion can occur with physically empty slots under a nonpermuting probe policy.',true);}}
function chainPut(k){key=k;cursor=mod(k,m);route=[cursor];snap('Select bucket '+cursor,'Only this bucket can hold an equal key.');const b=buckets[cursor];for(const v of b){comparisons++;extra.inspected=v.id;snap('Compare chain record','A map put must check for an existing equal key.');if(v.key===k){answer={status:'updated'};snap('Update existing key','The equality class is already represented; live count does not increase.',true);return;}}b.unshift({key:k,id:'K'+serial++});links++;answer={status:'inserted'};snap('Link at chain head','Every record is in its floor-modulo bucket; new head insertion follows the declared policy.',true);}
snap('Initial empty representation','Capacity, route policy and marker states are declared before processing keys.');
if(s.operation==='chain'){for(const k of s.keys)chainPut(k);for(const c of s.commands){if(c.type==='put'){chainPut(c.key);continue;}key=c.key;cursor=mod(key,m);const b=buckets[cursor];let j=-1;for(let i=0;i<b.length;i++){comparisons++;extra.inspected=b[i].id;snap('Inspect chain record','Compare keys, not merely hash codes.');if(b[i].key===key){j=i;break;}}if(j>=0&&c.type==='delete'){b.splice(j,1);links++;}answer={status:j<0?'absent':c.type==='delete'?'deleted':'found'};snap('Complete '+c.type,'The targeted bucket scan determines the result.',true);}}
else if(['open','shift','rebuild'].includes(s.operation)){for(const k of s.keys)runOpen({type:'put',key:k});if(s.operation==='shift'){if(s.policy!=='linear')throw Error('Backward shifting requires linear probing.');const target=s.commands.find(c=>c.type==='delete');if(!target)throw Error('Declare a deletion command for backward shifting.');key=target.key;const at=slots.findIndex(x=>x&&x!=='DELETED'&&x.key===key);if(at<0)throw Error('The shift target must be present.');let hole=at;slots[hole]=null;snap('Open temporary repair hole','This gap is temporary; do not issue a client search before repair completes.');for(let t=1;t<m;t++){let j=mod(at+t,m),v=slots[j];cursor=j;if(v===null)break;if(v==='DELETED')throw Error('The compact shift model starts without tombstones.');const h=mod(v.key,m);extra.distanceToHole=mod(hole-h,m);extra.distanceToSlot=mod(j-h,m);snap('Test record route','Move only when the repair hole lies on this record\'s forward route.');if(extra.distanceToHole<extra.distanceToSlot){slots[hole]=v;slots[j]=null;hole=j;moves++;snap('Shift one reachable record','Its new position is earlier on the same valid search route.');}}cursor=hole;answer={status:'deleted',hole};snap('Finish repaired cluster','The final hole can now be EMPTY without stranding any surviving key.',true);}
else if(s.operation==='rebuild'){const old=clone(slots),live=ids();extra.oldSlots=old;extra.oldCapacity=s.capacity;s.capacity=s.newCapacity;slots=Array(s.capacity).fill(null);snap('Allocate new routing context','Physical old slots cannot be copied to their old indices.');for(const k of live){const h=mod(k,s.capacity);let j=h;while(slots[j])j=mod(j+1,s.capacity);slots[j]=clone(old.find(v=>v&&v!=='DELETED'&&v.key===k));moves++;cursor=j;key=k;snap('Reinsert key '+k,'Recompute the new home and resolve collisions in the new table.');}answer={status:'rebuilt',keys:live};snap('Finish rebuild','Every live record has been reinserted under the new modulus.',true);}
else for(const c of s.commands)runOpen(c);}
else if(s.operation==='horner'){let value=0;extra.codes=s.keys;extra.prefix=0;extra.base=s.base;for(const c of s.keys){extra.previous=value;key=c;value=mod(s.base*value+c,m);extra.prefix++;extra.value=value;snap('Evaluate prefix '+extra.prefix,'Multiply the previous residue by the base, add the next code and normalize modulo capacity.',true,`H_{${extra.prefix}}=(${s.base}\\cdot${extra.previous}+${c})\\bmod${m}=${value}`);}answer={hash:value};}
else if(s.operation==='bloom'){slots=Array(m).fill(0);for(const k of s.keys){key=k;route=[];for(let i=0;i<s.hashes;i++){cursor=mod(k*(i+1)+i*i,m);route.push(cursor);slots[cursor]=1;probes++;snap('Set bit '+cursor,'An insertion never clears a shared bit; bit positions may repeat.');}snap('Complete filter insertion','All selected bits are set; no identity record is stored in this bit array.',true);}for(const c of s.commands){key=c.key;route=Array.from({length:s.hashes},(_,i)=>mod(key*(i+1)+i*i,m));answer={possiblyPresent:route.every(j=>slots[j]===1)};extra.testedBits=route;snap('Filter query','All bits set means possibly present, not certified dictionary membership.',true);}answer=answer||{bits:clone(slots)};}
else if(s.operation==='perfect'){if(new Set(s.keys).size!==s.keys.length)throw Error('Static perfect construction requires distinct keys.');buckets=Array.from({length:m},()=>[]);for(const k of s.keys)buckets[mod(k,m)].push({key:k,id:'K'+serial++});extra.second=[];extra.squaredSpace=buckets.reduce((n,b)=>n+b.length*b.length,0);snap('Compute first-level bucket sizes','Squared sizes determine the second-level allocation; bucket zero is included.');for(let b=0;b<m;b++){const keys=buckets[b].map(x=>x.key),size=keys.length**2;if(!size)continue;let prime=2003,chosen=null;outer:for(let a=1;a<prime;a++)for(let c=0;c<prime;c++){const targets=keys.map(k=>mod(mod(a*(k+999)+c,prime),size));if(new Set(targets).size===keys.length){chosen={a,b:c,prime,size,keys,targets,bucket:b};break outer;}}if(!chosen)throw Error('No sample perfect placement found.');extra.second.push(chosen);cursor=b;snap('Place bucket '+b+' without collisions','Encode k as k+999 in the 2003-element prime field, then deterministically search affine parameters; the randomized theorem is separate.');}answer={squaredSpace:extra.squaredSpace,second:clone(extra.second)};snap('Finish fixed-set placement','Stored keys have distinct second-level positions within each bucket; absent candidates still require equality checks.',true);}
else if(s.operation==='cuckoo'){extra.right=Array(m).fill(null);extra.pending=null;const choices=k=>[mod(k,m),mod(Math.floor(k/m),m)];for(const k of s.keys){let current={key:k,id:'K'+serial++},side=0,steps=0;extra.pending=current;snap('Begin cuckoo insertion','Each key has two declared candidate positions.');for(;steps<2*m&&current;steps++){key=current.key;cursor=choices(key)[side];extra.side=side;const a=side?extra.right:slots,previous=a[cursor];a[cursor]=current;current=previous;extra.pending=current;links++;snap('Place and displace','A displaced record tries its other candidate; pending records are shown separately.');side=1-side;}if(current){answer={status:'needs_rebuild',pending:current};snap('Stop bounded relocation','The attempted placement has not inserted every key; rebuilding or another placement strategy is required.',true);break;}answer={status:'inserted'};snap('Complete cuckoo insertion','No pending record remains and every placed key uses one of its two candidates.',true);}}
else if(s.operation==='robin'){for(const k of s.keys){let current={key:k,id:'K'+serial++},j=mod(k,m),dist=0;extra.pending=current;for(let t=0;t<m;t++){cursor=j;key=current.key;probes++;extra.displacement=dist;const v=slots[j];snap('Compare displacement','The more displaced record keeps the contested slot.');if(!v){slots[j]=current;extra.pending=null;snap('Finish Robin Hood insertion','The final displaced record reaches an empty slot.',true);current=null;break;}if(v.key===current.key){extra.pending=null;current=null;break;}const resident=mod(j-mod(v.key,m),m);if(dist>resident){slots[j]=current;current=v;dist=resident;moves++;extra.pending=current;snap('Exchange displacement claim','The resident becomes the pending record and continues from its current distance.');}j=mod(j+1,m);dist++;}if(current)throw Error('Robin Hood sample requires space.');}answer={status:'built'};}
return {spec:s,states,result:{...clone(mapState()),liveKeys:['chain','perfect'].includes(s.operation)?buckets.flat().map(x=>x.key):s.operation==='bloom'||s.operation==='horner'?[]:s.operation==='cuckoo'?ids().concat((extra.right||[]).filter(Boolean).map(v=>v.key)):ids()}};}
function nativeFormula(z){if(!z.formula)return '';const n=v=>v<0?'<mo>−</mo><mn>'+(-v)+'</mn>':'<mn>'+v+'</mn>';let body='';
if(z.kind==='horner')body='<msub><mi>H</mi>'+n(z.extra.prefix)+'</msub><mo>=</mo><mo>(</mo>'+n(z.extra.base)+'<mo>·</mo>'+n(z.extra.previous)+'<mo>+</mo>'+n(z.key)+'<mo>)</mo><mo>mod</mo>'+n(z.capacity)+'<mo>=</mo>'+n(z.extra.value);
else if(z.kind==='shift'&&z.extra.distanceToHole!==undefined)body='<mi>D</mi><mo>(</mo><mi>h</mi><mo>,</mo><mi>u</mi><mo>)</mo><mo>=</mo>'+n(z.extra.distanceToHole)+'<mspace width="1em"/><mi>D</mi><mo>(</mo><mi>h</mi><mo>,</mo><mi>v</mi><mo>)</mo><mo>=</mo>'+n(z.extra.distanceToSlot);
else body='<mi>h</mi><mo>(</mo>'+n(z.key)+'<mo>)</mo><mo>=</mo>'+n(z.key)+'<mo>mod</mo>'+n(z.capacity)+'<mo>=</mo>'+n(mod(z.key,z.capacity));return '<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow>'+body+'</mrow></math>';}
const rect=(id,x,y,w,h,value,label='',color='#f6fafc')=>`<g data-entity="${esc(id)}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${color}" stroke="#87a9b6"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle" class="hs-key">${esc(value)}</text>${label?`<text x="${x+w/2}" y="${y+h+20}" text-anchor="middle">${esc(label)}</text>`:''}</g>`;
function drawing(z){let out='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 400" role="img" aria-label="Exact hashing checkpoint"><defs><marker id="hashArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 1 L9 5 L0 9 Z" fill="#477c91"/></marker></defs><rect x="8" y="8" width="744" height="384" rx="12" fill="#f3f8fa"/><text x="28" y="38" class="hs-caption">'+esc(z.action)+'</text>';const txt=(x,y,s,cls='')=>`<text x="${x}" y="${y}" class="${cls}">${esc(s)}</text>`;
const row=(a,y,tag)=>{const width=Math.min(53,650/a.length),x=30;return a.map((v,i)=>{const active=z.cursor===i&&(z.kind!=='cuckoo'||(tag==='right')===Boolean(z.extra.side));const cell=rect('hole-'+tag+'-'+i,x+i*width,y,width-4,42,v===null?'–':v==='DELETED'?'DEL':typeof v==='number'?v:'','',active?'#d6edf5':v==='DELETED'?'#fff0d7':'#fff');return cell+txt(x+i*width+(width-4)/2,y+62,String(i))+ (v&&typeof v==='object'?rect((tag==='old'?'old-':'')+v.id,x+i*width,y,width-4,42,v.key,'',active?'#d6edf5':'#fff'):'');}).join('');};
if(z.kind==='chain'){const rh=Math.min(43,280/z.capacity);for(let i=0;i<z.capacity;i++){let y=58+i*rh;out+=rect('bucket-'+i,30,y,42,30,i);const b=z.buckets[i];for(let j=0;j<b.length;j++){const x=112+j*72;out+=`<path d="M${j?x-16:72} ${y+15} L${x} ${y+15}" stroke="#477c91" fill="none" marker-end="url(#hashArrow)" data-connector="true" data-source="${j?b[j-1].id:'bucket-'+i}" data-target="${b[j].id}"/>`+rect(b[j].id,x,y,56,30,b[j].key,'',b[j].id===z.extra.inspected?'#d6edf5':'#fff');}if(!b.length)out+=txt(112,y+20,'empty');}}
else if(z.kind==='perfect'){for(let i=0;i<z.capacity;i++){const y=52+i*23;out+=txt(30,y,'Bucket '+i+': '+z.buckets[i].map(x=>x.key).join(', '));}out+=txt(345,52,'Second-level stored positions');let r=0;for(const q of z.extra.second||[]){const y=82+r++*74;out+=txt(345,y-10,'Bucket '+q.bucket+' · '+q.size+' slots');const a=Array(q.size).fill(null);q.keys.forEach((k,i)=>a[q.targets[i]]={key:k});const w=Math.min(46,365/q.size);out+=a.map((v,i)=>rect('perfect-'+q.bucket+'-'+i,345+i*w,y,w-4,34,v?v.key:'–','')).join('');}out+=txt(30,338,'Squared allocation: '+(z.extra.squaredSpace??0));}
else if(z.kind==='horner'){out+=z.extra.codes?.map((c,i)=>rect('code-'+i,32+i*42,80,38,40,c,i,i<(z.extra.prefix||0)?'#d6edf5':'#fff')).join('')||'';out+=rect('previous',65,180,125,54,z.extra.previous??0,'previous residue')+rect('code',294,180,105,54,z.key??'–','next code')+rect('result',525,180,135,54,z.extra.value??0,'new residue');out+='<path d="M190 207 L294 207 M399 207 L525 207" stroke="#477c91" fill="none" marker-end="url(#hashArrow)"/>';out+=txt(70,305,'Multiply by base '+(z.extra.base??'')+', add code, then reduce modulo '+z.capacity);}
else if(z.kind==='bloom'){out+=row(z.slots,100,'bit');out+=txt(32,200,'Inserted/query key: '+(z.key??'none'));out+=txt(32,240,'Visited bit positions: '+z.route.join(', '));out+=txt(32,285,'These declared sample bit functions illustrate mechanism, not ideal independence.');if(z.answer)out+=txt(32,325,'Possibly present: '+z.answer.possiblyPresent);}
else{if(z.cursor!==null&&z.kind!=='cuckoo')out+=rect('probe',30+z.cursor*Math.min(53,650/z.slots.length),56,Math.min(53,650/z.slots.length)-4,32,'probe','','#d6edf5');out+=row(z.slots,104,'slot');if(z.kind==='rebuild'&&z.extra.oldSlots){out+=txt(30,185,'Old capacity '+z.extra.oldCapacity+' · records are reinserted, not copied');out+=row(z.extra.oldSlots,212,'old');}else if(z.kind==='cuckoo'){out+=txt(30,190,'Second candidate table');out+=row(z.extra.right||Array(z.capacity).fill(null),212,'right');out+=txt(30,325,'Pending record: '+(z.extra.pending?.key??'none'));}else{out+=txt(32,190,'Current key: '+(z.key??'none'));out+=txt(32,228,'Probe route: '+(z.route.join(' → ')||'not started'));out+=txt(32,266,'Last result: '+(z.answer?.status??'operation in progress'));if(z.kind==='shift')out+=txt(32,304,'Distance to hole / current slot: '+(z.extra.distanceToHole??'–')+' / '+(z.extra.distanceToSlot??'–'));if(z.kind==='robin')out+=txt(32,304,'Pending record / displacement: '+(z.extra.pending?.key??'none')+' / '+(z.extra.displacement??0));}}
out+=txt(32,376,'Probes '+z.probes+' · equality checks '+z.comparisons+' · moves '+z.moves+' · complete '+z.complete);return out.replace(/<text[^>]*><\/text>/g,'')+'</svg>';}
function makeModel(id,title,raw){const e=evaluate(raw);return {id,title,invariant:'Match the declared hash context, exact probe route and slot/bucket state. Only completed checkpoints certify a completed operation.',spec:e.spec,result:e.result,frames:e.states.map((z,i)=>({label:z.action,caption:z.why,svg:drawing(z),formula:z.formula,formulaHtml:nativeFormula(z),duration:800,index:i,snapshot:{inputs:e.spec,state:z,result:i===e.states.length-1?e.result:null},teaching:{currentState:z.action,operation:'Hash-table operation: '+z.action,why:z.why,reading:z.kind==='chain'?'Follow the selected bucket and compare real keys; stable K identifiers retain record identity.':'LIVE contains a key; DEL preserves a search route; the dash denotes EMPTY. Read the exact attempted positions and the stated policy.',checks:(()=>{const a=[{mathHtml:'Operation is complete',result:String(z.complete)}];if(z.cursor!==null&&['open','shift','rebuild','robin'].includes(z.kind)){const v=z.slots[z.cursor];a.push({mathHtml:'Current slot is EMPTY',result:String(v===null)},{mathHtml:'Current slot is DELETED',result:String(v==='DELETED')});if(v&&typeof v==='object')a.push({mathHtml:'Current live key equals requested key',result:String(v.key===z.key)});}if(z.kind==='shift'&&z.extra.distanceToHole!==undefined)a.push({mathHtml:'Distance to hole is less than distance to current position',result:String(z.extra.distanceToHole<z.extra.distanceToSlot)});return a;})()}}))};}
if(typeof module!=='undefined')module.exports={validate,probe,evaluate,makeModel,mod,gcd};if(typeof document==='undefined')return;
function mount(host,m){if(!host.querySelector('.hs-controls')){const c=document.createElement('div');c.className='hs-controls';c.innerHTML='<button data-reset>Restart</button><button data-prev>Previous</button><button data-play>Play</button><button data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.hs-stage').before(c);}for(const cls of['hs-caption','hs-formula','hs-print'])if(!host.querySelector('.'+cls)){const e=document.createElement('div');e.className=cls;host.append(e);}const player=AdvancedSimulations.mount(host,m,{topic:'a_hash',prefix:'hs',retainDrawing:true});
const updatePorts=()=>{const svg=host.querySelector('.hs-stage svg');if(!svg)return;for(const e of svg.querySelectorAll('[data-connector]')){const a=svg.querySelector('[data-entity="'+e.dataset.source+'"] rect'),b=svg.querySelector('[data-entity="'+e.dataset.target+'"] rect');if(!a||!b)continue;const aa=DiagramLayout.box(svg,a),bb=DiagramLayout.box(svg,b);e.setAttribute('d',`M${aa.x+aa.w} ${aa.y+aa.h/2} L${bb.x} ${bb.y+bb.h/2}`);}};
const observer=new MutationObserver(updatePorts);observer.observe(host.querySelector('.hs-stage'),{childList:true,subtree:true,attributes:true,attributeFilter:['x','y','width','height','transform']});updatePorts();const dispose=player.dispose.bind(player);player.dispose=()=>{observer.disconnect();dispose();};return player;}
async function boot(){const data=await(await fetch('a_hash-models.json')).json();globalThis.HashPlayers=[];for(const h of document.querySelectorAll('[data-hs-model]')){const m=data.models.find(x=>x.id===h.dataset.hsModel);if(!m)throw Error('Missing hash model');HashPlayers.push(mount(h,m));}const form=document.querySelector('#hs-form'),out=document.querySelector('#hs-output'),error=document.querySelector('#hs-error');let active;form.addEventListener('submit',e=>{e.preventDefault();try{const parts=form.elements.keys.value.split(',');if(parts.some(x=>!x.trim()))throw Error('Every comma-separated key must be present.');if(!form.elements.capacity.value.trim()||!form.elements.step.value.trim())throw Error('Capacity and step must be specified.');const raw={operation:form.elements.operation.value,capacity:Number(form.elements.capacity.value),keys:parts.map(x=>Number(x.trim())),policy:form.elements.policy.value,step:Number(form.elements.step.value)};if(form.elements.command.value!=='none'){if(!form.elements.target.value.trim())throw Error('Supply a command target key.');raw.commands=[{type:form.elements.command.value,key:Number(form.elements.target.value)}];}if(raw.operation==='rebuild')raw.newCapacity=Number(form.elements.newCapacity.value);if(raw.operation==='horner')raw.base=Number(form.elements.base.value);if(raw.operation==='bloom')raw.hashes=Number(form.elements.hashes.value);const model=makeModel('editable-hash','Your exact hashing experiment',raw);active?.dispose();out.innerHTML='<section class="hs-model"><h3>'+esc(model.title)+'</h3><div class="hs-stage"></div></section><h3>Exact result</h3><pre>'+esc(JSON.stringify(model.result,null,2))+'</pre>';active=mount(out.firstChild,model);globalThis.HashLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}boot().catch(e=>{document.querySelector('#hs-error').textContent=e.message;throw e;});
})();
